#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/device.h>
#include <zephyr/drivers/uart.h>
#include <zephyr/sys/ring_buffer.h>

#include <modem/backend/tty.h>

#include <string.h>
#include <stdlib.h>

#include <unistd.h>
#include <fcntl.h>
#include <termios.h>

static const struct device *uart_dev = DEVICE_DT_GET(DT_NODELABEL(uart0));
static int pty_leader;
static char pty_follower_name[32];

static K_SEM_DEFINE(event_sem, 0, 1);

#define TEST_DATA "test"
#define TEST_BUF_SIZE 16

static struct modem_backend_tty backend_uart;
static uint8_t backend_uart_rx_buf[64];
static uint8_t backend_uart_tx_buf[64];

static struct modem_backend_tty_config backend_uart_config = {
	.uart = DEVICE_DT_GET(DT_NODELABEL(uart0)),
	.rx_buf = backend_uart_rx_buf,
	.rx_buf_size = sizeof(backend_uart_rx_buf),
	.tx_buf = backend_uart_tx_buf,
	.tx_buf_size = sizeof(backend_uart_tx_buf),
};

static void event_callback(struct modem_backend *backend, enum modem_backend_event event,
			   void *user_data)
{
	if (event == MODEM_BACKEND_EVENT_RECEIVED_READY) {
		k_sem_give(&event_sem);
	}
}

static void write_to_pty(const char *data, size_t len)
{
	int ret = write(pty_leader, data, len);

	zassert_equal(ret, len, "write to pty failed");
}

static void *modem_backend_tty_suite_setup(void)
{
	pty_leader = posix_openpt(O_RDWR | O_NOCTTY);
	zassert_true(pty_leader >= 0, "posix_openpt failed");
	zassert_ok(grantpt(pty_leader), "grantpt failed");
	zassert_ok(unlockpt(pty_leader), "unlockpt failed");
	zassert_not_null(ptsname_r(pty_leader, pty_follower_name, sizeof(pty_follower_name)),
			 "ptsname_r failed");
	uart_native_sim_set_pts(uart_dev, pty_follower_name);

	modem_backend_tty_init(&backend_uart, &backend_uart_config);
	modem_backend_register_event_callback(&backend_uart.backend, event_callback, NULL);
	return NULL;
}

static void modem_backend_tty_suite_teardown(void *fixture)
{
	modem_backend_close(&backend_uart.backend);
	close(pty_leader);
}

static void modem_backend_tty_suite_before(void *fixture)
{
	k_sem_reset(&event_sem);
}

ZTEST(modem_backend_tty_suite, test_close_open)
{
	zassert_ok(modem_backend_open(&backend_uart.backend));
	modem_backend_close(&backend_uart.backend);
	zassert_ok(modem_backend_open(&backend_uart.backend));
}

ZTEST(modem_backend_tty_suite, test_receive)
{
	uint8_t buf[TEST_BUF_SIZE];
	size_t len = strlen(TEST_DATA);

	zassert_ok(modem_backend_open(&backend_uart.backend));

	write_to_pty(TEST_DATA, len);
	k_sleep(K_MSEC(100));

	zassert_equal(modem_backend_read(&backend_uart.backend, buf, len), len);
	zassert_mem_equal(buf, TEST_DATA, len);
}

ZTEST(modem_backend_tty_suite, test_receive_ready_event_not_raised)
{
	zassert_ok(modem_backend_open(&backend_uart.backend));

	zassert_not_equal(k_sem_take(&event_sem, K_MSEC(100)), 0, "Event was received");
}

ZTEST(modem_backend_tty_suite, test_receive_ready_event_raised)
{
	uint8_t buf[TEST_BUF_SIZE];
	size_t len = strlen(TEST_DATA);

	zassert_ok(modem_backend_open(&backend_uart.backend));

	write_to_pty(TEST_DATA, len);

	/* Wait for event */
	zassert_ok(k_sem_take(&event_sem, K_SECONDS(1)), "Event was not received");

	/* Read data and verify it */
	zassert_equal(modem_backend_read(&backend_uart.backend, buf, len), len);
	zassert_mem_equal(buf, TEST_DATA, len);
}

ZTEST_SUITE(modem_backend_tty_suite, NULL, modem_backend_tty_suite_setup,
	    modem_backend_tty_suite_before, modem_backend_tty_suite_teardown, NULL);
